import sys
from collections import defaultdict

def solve():
    input = sys.stdin.read().split()
    ptr = 0
    T = int(input[ptr])
    ptr += 1
    for _ in range(T):
        n, k = map(int, input[ptr:ptr+2])
        ptr +=2
        adj1 = defaultdict(list)
        adj2 = defaultdict(list)
        for __ in range(k):
            m = int(input[ptr])
            ptr +=1
            for ___ in range(m):
                u, v = map(int, input[ptr:ptr+2])
                ptr +=2
                if __ == 0:
                    adj1[u].append(v)
                    adj1[v].append(u)
                else:
                    adj2[u].append(v)
                    adj2[v].append(u)

        parent = [0]*(n+1)
        visited = [False]*(n+1)
        stack = [1]
        visited[1] = True
        while stack:
            u = stack.pop()
            for v in adj1[u]:
                if not visited[v]:
                    visited[v] = True
                    parent[v] = u
                    stack.append(v)

        root = 1
        for i in range(1, n+1):
            if not visited[i]:
                root = i
                break

        if root != 1:
            print("NO")
            continue

        visited = [False]*(n+1)
        stack = [1]
        visited[1] = True
        order = []
        while stack:
            u = stack.pop()
            order.append(u)
            for v in adj1[u]:
                if not visited[v]:
                    visited[v] = True
                    stack.append(v)

        order.reverse()
        res = []
        for u in order:
            for v in adj2[u]:
                if parent[v] == u:
                    res.append((v, u))
                elif parent[u] == v:
                    res.append((u, v))

        if len(res) != n-1:
            print("NO")
            continue

        print("YES")
        for u, v in res:
            print(u, v)

solve()
